import sqlite3, json

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row

# Find reservation A58410 in flight_bookings
cur = conn.execute(\"SELECT * FROM flight_bookings WHERE booking_id = 'A58410'\")
row = cur.fetchone()
if row:
    print('=== BOOKING A58410 ===')
    for k in row.keys():
        val = row[k]
        if isinstance(val, str) and (val.startswith('{') or val.startswith('[')):
            try:
                val = json.loads(val)
            except:
                pass
        print(f'  {k}: {json.dumps(val, indent=4) if isinstance(val, (dict, list)) else val}')
else:
    print('Booking A58410 not found')
"

