import sqlite3, json

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row

# Check if there are problematic flights
for r in conn.execute('SELECT flight_id, departure_time, arrival_time, dates_json FROM flights WHERE source_skill = ?', ('tau2Airline',)):
    dates = json.loads(r['dates_json'] or '{}')
    # Check for premium_economy in prices
    for d, info in dates.items():
        if 'prices' in info:
            if 'premium_economy' in info['prices']:
                print(f'Flight {r[\"flight_id\"]} date {d} has premium_economy in prices')
    if r['departure_time'] is None:
        print(f'Flight {r[\"flight_id\"]} has None departure_time')
" 2>&1

